package com.greenocean.backend;
import com.greenocean.backend.professional.service.*;import com.greenocean.backend.professional.dto.*;import com.greenocean.backend.common.exception.*;
import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.test.context.*;import org.springframework.transaction.annotation.Transactional;import org.junit.jupiter.api.*;import org.springframework.mock.web.MockMultipartFile;import java.time.*;import java.util.*;import java.net.*;import java.io.*;import static org.assertj.core.api.Assertions.*;
@SpringBootTest @AutoConfigureMockMvc @ActiveProfiles("test") @Transactional @org.springframework.test.annotation.DirtiesContext(classMode=org.springframework.test.annotation.DirtiesContext.ClassMode.AFTER_CLASS)
class PhaseP1Test extends PhaseO3Fixtures {
 @Autowired ProfessionalAuthority authority;@Autowired ProfessionalScheduling scheduling;@Autowired ProfessionalWorkflowService workflow;@Autowired CredentialDocuments docs;@Autowired ProfessionalDocumentStorage storage;
 static final ServerSocket scanner=server();static ServerSocket server(){try{var s=new ServerSocket(0,10,InetAddress.getLoopbackAddress());Thread.startVirtualThread(()->{while(!s.isClosed())try(var c=s.accept()){var in=new DataInputStream(c.getInputStream());while(in.readByte()!=0){}for(int n;(n=in.readInt())>0;)in.readNBytes(n);c.getOutputStream().write("stream: OK\0".getBytes(java.nio.charset.StandardCharsets.US_ASCII));}catch(IOException ignored){}});return s;}catch(IOException e){throw new IllegalStateException(e);}}
 @DynamicPropertySource static void scannerProperties(DynamicPropertyRegistry p){p.add("greenocean.clinic.scanning-approved",()->true);p.add("greenocean.clinic.scanner-port",scanner::getLocalPort);}
 @AfterAll static void closeScanner()throws Exception{scanner.close();}
 UUID apply(){return workflow.apply(learner.id(),new ProfessionalApplicationRequest("PSYCHOLOGIST","Synthetic psychologist","Synthetic specialty","Synthetic original professional application",2,List.of("General support"),List.of("فارسی"),null,"IR",null,null,null,null,List.of("Synthetic degree"),"QA-LICENSE",List.of("TEXT"),List.of("credential.pdf"))).id();}
 UUID upload(UUID id){return workflow.uploadDocument(id,learner.id(),new MockMultipartFile("file","credential.pdf","application/pdf","%PDF-1.4\nSYNTHETIC-PRIVATE-CREDENTIAL".getBytes())).id();}
 long revision(UUID id){return db.queryForObject("SELECT qualification_revision FROM professional_verifications WHERE id=?",Long.class,id);}
 ProfessionalAuthority.Decision decision(long revision,String state){return new ProfessionalAuthority.Decision(revision,state,"Synthetic independent review only, no real authority claim","PSYCHOLOGIST","Synthetic verified professional","Synthetic QA issuer","QA-LICENSE","OFFICIAL_REGISTER_HUMAN","https://my.pcoiran.ir/member/","SYNTHETIC-QA-VERIFICATION-NOT-REAL",Instant.now().minusSeconds(3600),Instant.now().plusSeconds(86400),Instant.now().plusSeconds(43200),List.of(new ProfessionalAuthority.Scope("IR","TEXT")));}
 @Test void encryptedQuarantineMustBeScannedBeforeIndependentExactRevisionReview(){UUID id=apply(),doc=upload(id);assertThatThrownBy(()->authority.decide(reviewer.id(),id,decision(revision(id),"VERIFIED"))).isInstanceOf(ConflictException.class);assertThatThrownBy(()->docs.read(learner.id(),doc,"Own credential inspection")).isInstanceOf(ForbiddenException.class);long old=revision(id);assertThat(docs.scan(reviewer.id(),doc,"Synthetic controlled scanner test").get("state")).isEqualTo("CLEAN");assertThatThrownBy(()->authority.decide(reviewer.id(),id,decision(old,"VERIFIED"))).isInstanceOf(ConflictException.class);authority.decide(reviewer.id(),id,decision(revision(id),"VERIFIED"));assertThat(db.queryForObject("SELECT professional_qualification_live(?)",Boolean.class,learner.id())).isTrue();assertThat(docs.read(learner.id(),doc,"Owner access to scanned credential")).contains("SYNTHETIC-PRIVATE-CREDENTIAL".getBytes());assertThatThrownBy(()->docs.read(other.id(),doc,"Foreign credential attempt")).isInstanceOf(ForbiddenException.class);assertThatThrownBy(()->authority.offer(learner.id(),"IR","TEXT")).isInstanceOf(ForbiddenException.class);}
 @Test void selfApprovalAndSelfDeclaredCategoryNeverGrantCare(){UUID id=apply();assertThatThrownBy(()->authority.decide(learner.id(),id,decision(revision(id),"VERIFIED"))).isInstanceOf(ForbiddenException.class);assertThat(db.queryForObject("SELECT professional_qualification_live(?)",Boolean.class,learner.id())).isFalse();assertThatThrownBy(()->scheduling.slot(learner.id(),new ProfessionalScheduling.Slot(Instant.now().plusSeconds(3600),Instant.now().plusSeconds(5400),"TEXT",0,"Asia/Tehran",true))).isInstanceOf(ForbiddenException.class);}
 @Test void draftFreeAvailabilityIsNotBookableAndDoesNotAuthorizeClinicalService(){apply();UUID slot=scheduling.slot(learner.id(),new ProfessionalScheduling.Slot(Instant.now().plusSeconds(3600),Instant.now().plusSeconds(5400),"TEXT",0,"Asia/Tehran",false));assertThat(db.queryForObject("SELECT status FROM professional_availability_slots WHERE id=?",String.class,slot)).isEqualTo("DRAFT");assertThat(db.queryForObject("SELECT price_units FROM professional_availability_slots WHERE id=?",Long.class,slot)).isZero();assertThatThrownBy(()->workflow.requestConsultation(learner.id(),other.id(),new CreateConsultationRequest(slot,null,null,"Synthetic booking attempt"))).isInstanceOf(ForbiddenException.class);}
 @Test void recurringCalendarMaterializesRealFutureDraftSlotsAndExceptionsCancelOnlyUnreserved(){apply();LocalDate day=LocalDate.now(ZoneId.of("Asia/Tehran")).plusDays(1);UUID rule=scheduling.rule(learner.id(),new ProfessionalScheduling.Rule("Asia/Tehran",day.getDayOfWeek().getValue(),"09:00","11:00",day,day,30,"TEXT",0,"REJECT"));assertThat(scheduling.materialize(learner.id(),rule,false).get("created")).isEqualTo(4);assertThat(scheduling.materialize(learner.id(),rule,false).get("created")).isEqualTo(0);Instant start=day.atTime(9,0).atZone(ZoneId.of("Asia/Tehran")).toInstant();scheduling.exception(learner.id(),new ProfessionalScheduling.ExceptionWindow(start,start.plusSeconds(3600),"Synthetic unavailable period"));assertThat(db.queryForObject("SELECT count(*) FROM professional_availability_slots WHERE professional_user_id=? AND status='CANCELLED'",Integer.class,learner.id())).isEqualTo(2);}
 @Test void overlapAndCredentialExpiryAreEnforcedAtCurrentRequest(){PhasePFixtures.qualified(db,learner.id(),reviewer.id());var in=new ProfessionalScheduling.Slot(Instant.now().plusSeconds(3600),Instant.now().plusSeconds(5400),"TEXT",1000,"Asia/Tehran",true);UUID saved=scheduling.slot(learner.id(),in);assertThat(scheduling.slot(learner.id(),in)).isEqualTo(saved);assertThatThrownBy(()->scheduling.slot(learner.id(),new ProfessionalScheduling.Slot(in.startsAt().plusSeconds(60),in.endsAt().plusSeconds(60),"TEXT",1000,"Asia/Tehran",true))).isInstanceOf(ConflictException.class);db.update("UPDATE professional_verifications SET valid_from=CURRENT_TIMESTAMP-INTERVAL '3 days',valid_until=CURRENT_TIMESTAMP-INTERVAL '1 day',recheck_at=CURRENT_TIMESTAMP-INTERVAL '2 days' WHERE professional_user_id=?",learner.id());assertThatThrownBy(()->authority.offer(learner.id(),"IR","TEXT")).isInstanceOf(ForbiddenException.class);}
 @Test void recurrenceHandlesGapAndOverlapWithoutInventingInstants(){ZoneId berlin=ZoneId.of("Europe/Berlin");assertThat(ProfessionalScheduling.resolve(LocalDateTime.of(2027,3,28,2,30),berlin,"REJECT")).isEmpty();var local=LocalDateTime.of(2027,10,31,2,30);assertThat(ProfessionalScheduling.resolve(local,berlin,"REJECT")).isEmpty();assertThat(Duration.between(ProfessionalScheduling.resolve(local,berlin,"EARLIER").orElseThrow(),ProfessionalScheduling.resolve(local,berlin,"LATER").orElseThrow())).isEqualTo(Duration.ofHours(1));}
 @Test void legacyManualApprovalsAndManualCleanLabelsCannotBypassEvidence(){UUID id=apply(),doc=upload(id);assertThatThrownBy(()->adminPlaceholder(id)).isInstanceOf(ConflictException.class);assertThatThrownBy(()->adminDocument(doc)).isInstanceOf(ConflictException.class);}
 @Autowired com.greenocean.backend.moderation.repository.AdminRepository adminRepository;
 void adminPlaceholder(UUID id){adminRepository.updateVerification(id,reviewer.id(),"APPROVE_VERIFICATION","Synthetic manual attempt");}void adminDocument(UUID id){adminRepository.updateDocumentScan(id,reviewer.id(),"CLEAN");}
 @Test void revocationCancelsFutureOffersAndRemovesReadiness(){UUID id=PhasePFixtures.qualified(db,learner.id(),reviewer.id());scheduling.slot(learner.id(),new ProfessionalScheduling.Slot(Instant.now().plusSeconds(3600),Instant.now().plusSeconds(5400),"TEXT",0,"Asia/Tehran",true));authority.decide(reviewer.id(),id,decision(revision(id),"REVOKED"));assertThat(db.queryForObject("SELECT professional_qualification_live(?)",Boolean.class,learner.id())).isFalse();assertThat(db.queryForObject("SELECT count(*) FROM professional_availability_slots WHERE professional_user_id=? AND status='AVAILABLE'",Integer.class,learner.id())).isZero();}
 @Test void sameDraftRetryPublishAndCancelPreserveServerState(){PhasePFixtures.qualified(db,learner.id(),reviewer.id());var in=new ProfessionalScheduling.Slot(Instant.now().plusSeconds(3600),Instant.now().plusSeconds(5400),"TEXT",0,"Asia/Tehran",false);UUID id=scheduling.slot(learner.id(),in);assertThat(scheduling.slot(learner.id(),in)).isEqualTo(id);scheduling.publish(learner.id(),id,1);scheduling.publish(learner.id(),id,1);assertThat(db.queryForObject("SELECT status FROM professional_availability_slots WHERE id=?",String.class,id)).isEqualTo("AVAILABLE");scheduling.cancelSlot(learner.id(),id,2);scheduling.cancelSlot(learner.id(),id,2);assertThat(scheduling.slot(learner.id(),in)).isNotEqualTo(id);}
 @Test void remindersAreExplicitPrivateAndExactlyOnce(){PhasePFixtures.qualified(db,learner.id(),reviewer.id());Instant start=Instant.now().plusSeconds(3590),end=start.plusSeconds(1800);UUID slot=scheduling.slot(learner.id(),new ProfessionalScheduling.Slot(start,end,"TEXT",0,"Asia/Tehran",true));UUID appointment=db.queryForObject("INSERT INTO consultation_requests(requester_user_id,professional_user_id,scheduled_at,consultation_mode,note,status,availability_slot_id) VALUES(?,?,?,'TEXT','Private synthetic patient note','CONFIRMED',?) RETURNING id",UUID.class,other.id(),learner.id(),ProfessionalAuthority.time(start),slot);var reminders=new ProfessionalReminders(db,authority,true);assertThat(reminders.dispatch()).isZero();reminders.preference(other.id(),appointment,true);assertThat(reminders.dispatch()).isEqualTo(1);assertThat(reminders.dispatch()).isZero();assertThat(db.queryForList("SELECT title,body FROM notifications WHERE user_id=?",other.id()).toString()).doesNotContain("Private synthetic patient note","Synthetic professional");}
 @Test void ownProfessionalArchiveDoesNotExportAnotherQualification(){UUID application=apply();upload(application);assertThat(archives.archive(learner.id()).professionalCare().toString()).contains("QA-LICENSE","qualifications");assertThat(archives.archive(other.id()).professionalCare().get("qualifications").toString()).isEqualTo("[]");}
 @Test void appointmentReadinessDependsOnCurrentSessionEvidence(){PhasePFixtures.qualified(db,learner.id(),reviewer.id());UUID slot=db.queryForObject("INSERT INTO professional_availability_slots(id,professional_user_id,starts_at,ends_at,consultation_mode,status,governed) VALUES(uuidv7(),?,CURRENT_TIMESTAMP-INTERVAL '1 minute',CURRENT_TIMESTAMP+INTERVAL '29 minutes','TEXT','BOOKED',TRUE) RETURNING id",UUID.class,learner.id());UUID appointment=db.queryForObject("INSERT INTO consultation_requests(requester_user_id,professional_user_id,scheduled_at,consultation_mode,status,availability_slot_id) VALUES(?,?,CURRENT_TIMESTAMP-INTERVAL '1 minute','TEXT','CONFIRMED',?) RETURNING id",UUID.class,other.id(),learner.id(),slot);assertThat(scheduling.readiness(other.id(),appointment).get("professionalReady")).isEqualTo(false);scheduling.checkin(learner.id(),learner.session(),appointment);assertThat(scheduling.readiness(other.id(),appointment).get("professionalReady")).isEqualTo(true);db.update("UPDATE user_sessions SET revoked_at=CURRENT_TIMESTAMP WHERE id=?",learner.session());assertThat(scheduling.readiness(other.id(),appointment).get("professionalReady")).isEqualTo(false);}
}
